<?php
declare(strict_types=1);

require_once __DIR__ . '/report_pdf.php';

/*
 * SHARED REPORT EXPORT: one report array (see sources/report_pdf.php) gives
 * the PDF and the CSV, so both always have the same columns and all rows.
 * CSV: UTF-8 with BOM (Excel shows "–" and "ñ" correctly) and the same
 * header lines as the PDF (clinic, branch, report, period, filters,
 * generated by, generated at).
 */

/** Report header data for the signed-in user. */
function reportMeta(mysqli $conn, int $userId, string $branchLabel, string $period, string $filters = ''): array
{
    $stmt = $conn->prepare('SELECT u.username, r.role_name FROM users u LEFT JOIN roles r ON r.role_id = u.role_id WHERE u.user_id = ?');
    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $user = $stmt->get_result()->fetch_assoc() ?: [];
    $stmt->close();
    return [
        'branch' => $branchLabel,
        'period' => $period,
        'filters' => $filters,
        'generated_by' => trim(($user['username'] ?? 'User') . ' (' . ($user['role_name'] ?? '') . ')'),
        'generated_at' => date('M d, Y h:i A'),
    ];
}

/** "Oct 01, 2026 – Oct 27, 2026" (or one day). */
function reportPeriodText(?string $from, ?string $to): string
{
    if (!$from && !$to) return 'All dates';
    $f = $from ? date('M d, Y', strtotime($from)) : '…';
    $t = $to ? date('M d, Y', strtotime($to)) : '…';
    return $f === $t ? $f : $f . ' – ' . $t;
}

/** Branch name, or "All branches" for null. */
function reportBranchName(mysqli $conn, ?string $branchId): string
{
    if ($branchId === null || $branchId === '') return 'All branches';
    $stmt = $conn->prepare('SELECT branch_name FROM branches WHERE branch_id = ?');
    $stmt->bind_param('s', $branchId);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    $stmt->close();
    return $row ? (string)$row['branch_name'] : $branchId;
}

/** Cell text for CSV: plain text, and no formula injection in Excel. */
function reportCsvCell($value): string
{
    if (is_array($value)) $value = $value['text'] ?? '';
    $text = (string)$value;
    if ($text !== '' && preg_match('/^[=+@\t\r]/', $text)) $text = "'" . $text;
    return $text;
}

/** The CSV of a report as a string (UTF-8 with BOM). */
function reportCsvBuild(array $report, array $meta): string
{
    $out = fopen('php://temp', 'r+');
    fwrite($out, "\xEF\xBB\xBF");
    $put = static function (array $cells) use ($out): void { fputcsv($out, array_map('reportCsvCell', $cells)); };
    $put([REPORT_CLINIC_NAME]);
    $put(['Report', $report['title'] ?? '']);
    $put(['Branch', $meta['branch'] ?? '']);
    $put(['Period', $meta['period'] ?? '']);
    if (($meta['filters'] ?? '') !== '') $put(['Filters', $meta['filters']]);
    $put(['Generated by', $meta['generated_by'] ?? '']);
    $put(['Generated at', ($meta['generated_at'] ?? '') . ' (Manila time)']);
    if (!empty($report['summary'])) {
        $put([]);
        $put([(string)($report['summary_title'] ?? 'Summary')]);
        foreach ($report['summary'] as $label => $value) $put([$label, $value]);
    }
    foreach ($report['sections'] ?? [] as $section) {
        $put([]);
        if (!empty($section['title'])) $put([$section['title']]);
        $keep = [];
        foreach ($section['columns'] as $i => $c) if (empty($c['screen_only'])) $keep[] = $i;
        $put(array_map(static fn($k) => $section['columns'][$k]['label'], $keep));
        if (!$section['rows']) $put([(string)($section['empty'] ?? 'No records match the selected filters.')]);
        foreach ($section['rows'] as $row) $put(array_map(static fn($k) => $row[$k] ?? '', $keep));
        if (isset($section['totals'])) $put(array_map(static fn($k) => $section['totals'][$k] ?? '', $keep));
    }
    if (!empty($report['notes'])) {
        $put([]);
        $put([(string)($report['notes_title'] ?? 'Notes')]);
        foreach ($report['notes'] as $note) $put([$note]);
    }
    rewind($out);
    $csv = stream_get_contents($out);
    fclose($out);
    return $csv;
}

/** Safe download file name: "Approval_Control_Report_SBI-002_2026-10-01_to_2026-10-27". */
function reportFileName(string $title, string $suffix = ''): string
{
    $name = preg_replace('/[^A-Za-z0-9_-]+/', '_', trim($title . ($suffix !== '' ? '_' . $suffix : '')));
    return trim((string)$name, '_') ?: 'Report';
}

/** Send the report as a PDF or CSV download and stop. */
function reportSend(array $report, array $meta, string $format, string $fileBase): void
{
    $format = strtolower($format) === 'csv' ? 'csv' : 'pdf';
    $body = $format === 'csv' ? reportCsvBuild($report, $meta) : reportPdfBuild($report, $meta);
    while (ob_get_level() > 0) ob_end_clean();
    header('Content-Type: ' . ($format === 'csv' ? 'text/csv; charset=UTF-8' : 'application/pdf'));
    header('Content-Disposition: attachment; filename="' . reportFileName($fileBase) . '.' . $format . '"');
    header('Content-Length: ' . strlen($body));
    header('Cache-Control: private, no-store');
    echo $body;
    exit;
}
